values ('why-is-the-sky-blue', 'Why Is the Sky Blue?', 'Sunlight, tiny air molecules and one surprisingly steep formula explain blue skies and red sunsets.', 'article',
  (select id from public.categories where slug = 'science'), null, 'Polymath Team', array['physics', 'light', 'atmosphere']::text[],
  'free', null, 1, false, 'published', '2026-10-31T09:00:00.000Z',
  '<p>Sunlight looks white, but it is a mix of every colour of the rainbow. On its way through the atmosphere it bumps into nitrogen and oxygen molecules that are far smaller than the wavelength of light — and that is where the blue comes from.</p>
', '[{"id":"rayleigh-scattering","text":"Rayleigh scattering","level":2},{"id":"then-why-isn-t-the-sky-violet","text":"Then why isn’t the sky violet?","level":2},{"id":"red-sunsets","text":"Red sunsets","level":2}]'::jsonb)
