insert into public.content_bodies (content_id, body_md, body_html)
select id, '
The Pomodoro Technique, created by Francesco Cirillo in the late 1980s, breaks work into short, focused intervals separated by breaks.

<!-- more -->

## The basic cycle

1. Pick **one** task.
2. Set a timer for **25 minutes** and work on nothing else.
3. Take a **5-minute** break — stand up, stretch, look away from screens.
4. After four rounds, take a longer **15–30 minute** break.

## The details that make it work

- **Write distractions down** instead of acting on them. Deal with the list during breaks.
- **Plan your pomodoros** at the start of the day; estimating builds a sense of how long things really take.
- **Protect the break.** Scrolling your phone is not rest.

> [!TIP]
> If 25 minutes feels too short for deep work like coding or composing, try 50/10. The principle — focused sprints with real breaks — matters more than the exact numbers.
', '<p>The Pomodoro Technique, created by Francesco Cirillo in the late 1980s, breaks work into short, focused intervals separated by breaks.</p>
<!-- more -->
<h2 id="the-basic-cycle">The basic cycle</h2>
<ol>
<li>Pick <strong>one</strong> task.</li>
<li>Set a timer for <strong>25 minutes</strong> and work on nothing else.</li>
<li>Take a <strong>5-minute</strong> break — stand up, stretch, look away from screens.</li>
<li>After four rounds, take a longer <strong>15–30 minute</strong> break.</li>
</ol>
<h2 id="the-details-that-make-it-work">The details that make it work</h2>
<ul>
<li><strong>Write distractions down</strong> instead of acting on them. Deal with the list during breaks.</li>
<li><strong>Plan your pomodoros</strong> at the start of the day; estimating builds a sense of how long things really take.</li>
<li><strong>Protect the break.</strong> Scrolling your phone is not rest.</li>
</ul>
<blockquote class="callout callout-tip">
<p class="callout-title">Tip</p>
<p>If 25 minutes feels too short for deep work like coding or composing, try 50/10. The principle — focused sprints with real breaks — matters more than the exact numbers.</p>
</blockquote>
' from public.contents where slug = 'pomodoro-technique-done-right'
on conflict (content_id) do nothing;

